const binaryKeys = Object.keys($binary || {});

// 1. Validate Image Count (1 to 10)
if (binaryKeys.length === 0) {
  return [{
    json: {
      isValid: false,
      errorCode: 'NO_IMAGES_UPLOADED',
      errorMessage: 'Please upload at least 1 image (up to 10 images supported).'
    }
  }];
}

if (binaryKeys.length > 10) {
  return [{
    json: {
      isValid: false,
      errorCode: 'TOO_MANY_IMAGES',
      errorMessage: 'Maximum 10 images allowed per diagnosis request. Please select between 1 and 10 photos.'
    }
  }];
}

// 2. Validate Selected Crop (Strictly ONE crop required)
const rawCrop = $json.body?.crop || $json.query?.crop || null;

if (!rawCrop || typeof rawCrop !== 'string' || rawCrop.trim() === '') {
  return [{
    json: {
      isValid: false,
      errorCode: 'INVALID_CROP',
      errorMessage: 'Please select exactly one target crop for this diagnosis case.'
    }
  }];
}

const cropTrimmed = rawCrop.trim();
if (cropTrimmed.includes(',') || cropTrimmed.includes(';') || Array.isArray(rawCrop)) {
  return [{
    json: {
      isValid: false,
      errorCode: 'MULTIPLE_CROPS_NOT_SUPPORTED',
      errorMessage: 'Only one crop can be diagnosed per request. Please submit separate requests for different crops.'
    }
  }];
}

// 3. Validate and Extract Binary Images
const imagesList = [];
for (let i = 0; i < binaryKeys.length; i++) {
  const key = binaryKeys[i];
  const bin = $binary[key];
  const mimeType = bin.mimeType || 'image/jpeg';

  if (!mimeType.startsWith('image/')) {
    return [{
      json: {
        isValid: false,
        errorCode: 'INVALID_FILE_TYPE',
        errorMessage: `File '${bin.fileName || key}' is not a supported image format (JPEG, PNG, WEBP).`
      }
    }];
  }

  let base64Data = '';
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    base64Data = buffer.toString('base64');
  } catch (e) {
    base64Data = bin.data || '';
  }

  imagesList.push({
    mimeType: mimeType,
    data: base64Data,
    fileName: bin.fileName || `image_${i+1}.jpg`
  });
}

// 4. Extract and Map Language
const langMap = {
  'en': 'English',
  'kn': 'Kannada',
  'ta': 'Tamil',
  'te': 'Telugu',
  'ml': 'Malayalam',
  'hi': 'Hindi'
};
const rawLang = String($json.body?.language || $json.query?.language || 'en').toLowerCase().trim();
const languageCode = langMap[rawLang] ? rawLang : (Object.keys(langMap).find(k => langMap[k].toLowerCase() === rawLang) || 'en');
const requestedLanguage = langMap[languageCode] || 'English';

const symptoms = $json.body?.symptoms || $json.body?.farmer_notes || $json.query?.symptoms || null;
const latitude = $json.body?.latitude || $json.query?.latitude || null;
const longitude = $json.body?.longitude || $json.query?.longitude || null;
const state = $json.body?.state || 'South India';

// 5. Pre-build Clean Gemini Multimodal Payload with Realism & Deterministic Configuration
const promptText = `Expert Plant Pathologist AI for South Indian agriculture.
CASE: Crop="${cropTrimmed}", Images=${imagesList.length}${symptoms ? `, Symptoms="${symptoms}"` : ''}, Language=${requestedLanguage}.

RULES:
1. CROP MISMATCH: If images do NOT match "${cropTrimmed}": health_status="Uncertain", confidence=0.20, disease="Unknown", explain mismatch in user_message (${requestedLanguage}).
2. LOW QUALITY / BLUR / DISTANT / POOR LIGHTING:
- If photos are blurry, low-resolution (e.g. 240p/360p), poorly lit, or taken from far away:
  * DO NOT hallucinate or pretend certainty.
  * If lesion details are ambiguous or not discernible: health_status="Uncertain", confidence between 0.30 and 0.50 (low confidence). Give suspected disease if any, and gently advise the farmer in user_message (${requestedLanguage}) to take a closer, clearer photo in good daylight.
  * If key symptoms are identifiable despite low quality: diagnose the condition, but calibrate confidence realistically (e.g. 0.50 - 0.70) reflecting image quality.
3. HEALTHY: If healthy: health_status="Healthy", disease="None", severity="None", standard care advice in recommendations (${requestedLanguage}).
4. DISEASED: If diseased, diagnose condition for "${cropTrimmed}".
- disease: Canonical agronomic disease name in ${requestedLanguage} (e.g. "Anthracnose (Fruit Rot / Dieback)")
- severity: "Mild" | "Moderate" | "Severe"
- symptoms: Array in ${requestedLanguage}
- recommendations: Practical actionable steps in ${requestedLanguage}
- prevention: Practical prevention steps in ${requestedLanguage}
- regional_advice: Practical advice for South Indian farmers in ${requestedLanguage}
- user_message: Direct message to farmer in ${requestedLanguage}

MANDATORY: Return ALL natural language fields in ${requestedLanguage}. Keep JSON keys in English.

JSON format:
{
  "crop": "${cropTrimmed}",
  "health_status": "Healthy",
  "disease": "None",
  "confidence": 0.95,
  "severity": "None",
  "symptoms": ["..."],
  "recommendations": ["..."],
  "prevention": ["..."],
  "regional_advice": "...",
  "user_message": "..."
}`;

const imageParts = imagesList.map(img => ({
  inlineData: {
    mimeType: img.mimeType || 'image/jpeg',
    data: img.data
  }
}));

const geminiPayload = {
  contents: [
    {
      parts: [
        { text: promptText },
        ...imageParts
      ]
    }
  ],
  generationConfig: {
    responseMimeType: 'application/json',
    temperature: 0.0,
    seed: 42
  }
};

return [{
  json: {
    isValid: true,
    crop: cropTrimmed,
    imageCount: imagesList.length,
    images: imagesList,
    symptoms: symptoms,
    language: languageCode,
    requestedLanguage: requestedLanguage,
    latitude: latitude,
    longitude: longitude,
    state: state,
    geminiPayload: geminiPayload
  }
}];

const res = $json;

try {
  if (res.error || !res.candidates || !res.candidates[0]?.content?.parts?.[0]?.text) {
    return [{ json: { is_usable: false, error_reason: 'HTTP_OR_EMPTY_RESPONSE' } }];
  }

  const rawText = res.candidates[0].content.parts[0].text;
  const cleaned = rawText.replace(/```json\n?|\n?```/g, '').trim();
  const parsed = JSON.parse(cleaned);

  if (!parsed.crop || !parsed.health_status || parsed.confidence === undefined) {
    return [{ json: { is_usable: false, error_reason: 'MISSING_REQUIRED_FIELDS' } }];
  }

  return [{ json: { is_usable: true, model_used: 'Gemini 3.5 Flash Lite', parsed_data: parsed } }];
} catch (e) {
  return [{ json: { is_usable: false, error_reason: 'INVALID_JSON_SYNTAX', details: e.message } }];
}

